import re
import requests


def task_func(input):
    """
    Extract an API endpoint from the input string, perform a GET request,
    and return the response data as a dictionary.
    """
    if input is None:
        return {"error": "No input provided"}

    text = str(input)

    # Find the first HTTP/HTTPS URL in the input text.
    match = re.search(r'https?://[^\s<>"\'\)\]]+', text)
    if not match:
        return {"error": "No API endpoint found"}

    endpoint = match.group(0).rstrip(".,;:!?)]}'\"")

    try:
        response = requests.get(endpoint, timeout=10)
    except requests.RequestException as exc:
        return {"error": f"Request failed: {exc}"}

    try:
        data = response.json()
    except ValueError:
        # If the response is not valid JSON, return the text payload in a dict.
        return {"data": response.text}

    # Ensure the function always returns a dict.
    if isinstance(data, dict):
        return data
    return {"data": data}
